-- CREATE + INSERT tabla temas (navegacion publica SEO /temas)
-- Fuente: ingesta/intros_temas_generadas.json (66 registros)
-- Indice por los 66 subtemas finos (columna tema), agrupados visualmente
-- por las 11 areas generales en la UI de /temas -- sin columna area aqui,
-- se deriva con split_part(tema, ' - ', 1) igual que en preguntas.area.

BEGIN;

CREATE TABLE IF NOT EXISTS temas (
  slug TEXT PRIMARY KEY,
  tema TEXT NOT NULL,
  intro TEXT NOT NULL,
  num_preguntas INT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

DO $$
DECLARE
  total_antes int;
BEGIN
  SELECT COUNT(*) INTO total_antes FROM public.temas;
  IF total_antes != 0 THEN
    RAISE EXCEPTION 'La tabla temas ya tiene % filas -- abortando para no duplicar.', total_antes;
  END IF;
END $$;


DO $$
DECLARE
  total_despues int;
  desajustes int;
BEGIN
  SELECT COUNT(*) INTO total_despues FROM public.temas;
  IF total_despues != 66 THEN
    RAISE EXCEPTION 'Se esperaban 66 filas en temas, hay % -- abortando.', total_despues;
  END IF;

  -- LEFT JOIN a proposito: un tema sin fila coincidente en preguntas (p.n_real
  -- IS NULL) es tan grave como un num_preguntas desajustado, y debe abortar
  -- igual -- no solo los casos donde SI hay coincidencia pero el numero falla.
  SELECT COUNT(*) INTO desajustes
  FROM public.temas t
  LEFT JOIN (
    SELECT tema, COUNT(*)::int AS n_real
    FROM public.preguntas
    GROUP BY tema
  ) p ON p.tema = t.tema
  WHERE p.n_real IS NULL OR p.n_real != t.num_preguntas;

  IF desajustes != 0 THEN
    RAISE EXCEPTION '% temas tienen num_preguntas desajustado (o sin coincidencia) respecto a preguntas -- abortando.', desajustes;
  END IF;

  RAISE NOTICE 'OK: % filas en temas, num_preguntas cuadra con preguntas para las % coincidencias.', total_despues, 66;
END $$;

COMMIT;
